using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed))
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded: {probed!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo(Person) returned false");

// Demonstrate the "not available" branch using a resolver that knows nothing
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) => { if (ti.Type == typeof(Secret)) throw new NotSupportedException(); } }
    }
};

// For a truly absent type, use an empty resolver:
var empty = new JsonSerializerOptions { TypeInfoResolver = JsonTypeInfoResolver.Combine() };

if (empty.TryGetTypeInfo(typeof(Secret), out _))
    Console.WriteLine("Secret metadata found (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo(Secret) returned false — no metadata available");

record Person(string Name, int Age);
record Secret(string Value);

